const body = $input.all()[0].json.body || $input.all()[0].json;

const mandatId = parseInt(body.mandat_id);
if (!mandatId || isNaN(mandatId)) {
  throw new Error('mandat_id est requis et doit être un entier');
}

const fileIds = body.file_ids;
if (!Array.isArray(fileIds) || fileIds.length === 0) {
  throw new Error('file_ids doit être un tableau non vide d\'IDs Google Drive');
}

const selectQuery = "SELECT m.id, m.ref, m.poste, m.lieu, m.secteur, m.mission, m.description_offre, m.profil_requis, m.drive_folder_id FROM mandats m WHERE m.id = " + mandatId + " LIMIT 1";

return [{
  json: {
    mandat_id: mandatId,
    file_ids: fileIds,
    select_query: selectQuery
  }
}];

const mandat = $input.all()[0].json;
if (!mandat || !mandat.id) {
  throw new Error('Mandat introuvable ou inactif');
}

const fileIds = $node['Valider et préparer requête'].json.file_ids;

return fileIds.map(fileId => ({
  json: {
    file_id: fileId,
    cv_url: 'https://drive.google.com/file/d/' + fileId + '/view',
    mandat_id: mandat.id,
    mandat_ref: mandat.ref,
    poste: mandat.poste || '',
    lieu: mandat.lieu || '',
    secteur: mandat.secteur || '',
    mission: mandat.mission || '',
    description_offre: mandat.description_offre || '',
    profil_requis: mandat.profil_requis || '',
    drive_folder_id: mandat.drive_folder_id || null
  }
}));

const extracted = $node['Information Extractor'].json.output;
const fileData = $node['Préparer fichiers à traiter'].json;

const nom = (extracted.nom || '').replace(/"/g, '');
const prenom = (extracted.prenom || '').replace(/"/g, '');
const dernier_poste = (extracted.dernier_poste || '').replace(/"/g, '');
const annees_exp = extracted.annees_experience || 0;
const formation = ((extracted.niveau_formation || '') + ' ' + (extracted.domaine_formation || '')).replace(/"/g, '');
const secteurs = (extracted.secteurs_exp || []).join(', ').replace(/"/g, '');
const competences = (extracted.competences_cles || []).join(', ').replace(/"/g, '');
const poste = (fileData.poste || '').replace(/"/g, '');
const secteur = (fileData.secteur || '').replace(/"/g, '');
const profil = (fileData.profil_requis || '').replace(/"/g, '');

const prompt = "Analyse ce profil candidat et evalue sa correspondance avec la fiche de poste. " +
  "PROFIL : Nom : " + nom + " " + prenom + ". " +
  "Dernier poste : " + dernier_poste + ". " +
  "Experience : " + annees_exp + " ans. " +
  "Formation : " + formation + ". " +
  "Secteurs : " + secteurs + ". " +
  "Competences : " + competences + ". " +
  "FICHE DE POSTE : Poste : " + poste + ". " +
  "Secteur : " + secteur + ". " +
  "Profil requis : " + profil + ". " +
  "SCORING SUR 100 POINTS STRICT : " +
  "Experiences similaires ou transposables 40pts, " +
  "Formation et diplomes pertinents 20pts, " +
  "Competences techniques requises 20pts, " +
  "Soft skills 10pts, " +
  "Adequation geographique 10pts. " +
  "REGLES ABSOLUES : " +
  "Score 75-100 ET experience directe dans le secteur = A_RETENIR. " +
  "Score 40-74 = A_ETUDIER. " +
  "Score 0-39 = NON_RETENU. " +
  "Ne jamais donner 100/100 sauf correspondance parfaite sur TOUS les criteres. " +
  "Penaliser absence de competences cles. " +
  "Reponds UNIQUEMENT avec un objet JSON valide contenant : " +
  "score (nombre entier), " +
  "score_justification (texte factuel), " +
  "points_forts (tableau de 4 elements max), " +
  "points_faibles (tableau de 4 elements max), " +
  "recommendation (A_RETENIR ou A_ETUDIER ou NON_RETENU).";

return [{
  json: {
    prompt: prompt,
    mandat_id: fileData.mandat_id,
    mandat_ref: fileData.mandat_ref,
    drive_folder_id: fileData.drive_folder_id,
    poste: fileData.poste,
    file_id: fileData.file_id
  }
}];

