const extracted = $node['Information Extractor'].json.output;
const fileData = $node['Préparer fichiers à traiter'].json;

const escapeSql = (str) => String(str || '').replace(/'/g, "''");
const escapeJson = (arr) => JSON.stringify(arr || []).replace(/'/g, "''");

const scoreResponse = $input.all()[0].json;
const analysisText = scoreResponse.choices?.[0]?.message?.content || '';

let scoring = {};
try {
  const cleaned = analysisText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  scoring = JSON.parse(cleaned);
} catch(e) {
  scoring = {
    score: 0,
    score_justification: 'Erreur parsing scoring',
    points_forts: [],
    points_faibles: [],
    recommendation: 'A_ETUDIER'
  };
}

const score = Math.min(100, Math.max(0, parseFloat(scoring.score) || 0));

const genreRaw = String(extracted.genre || '').trim();
let genre = 'Inconnu';
if (['M', 'm', 'Masculin', 'masculin', 'Male', 'male', 'Homme', 'homme'].includes(genreRaw)) {
  genre = 'M';
} else if (['F', 'f', 'Féminin', 'feminin', 'Féminine', 'Female', 'female', 'Femme', 'femme'].includes(genreRaw)) {
  genre = 'F';
}

return [{
  json: {
    mandat_id: fileData.mandat_id,
    mandat_ref: fileData.mandat_ref,
    drive_folder_id: fileData.drive_folder_id,
    cv_url: fileData.cv_url,
    poste: fileData.poste,
    nom: escapeSql(extracted.nom || ''),
    prenom: escapeSql(extracted.prenom || ''),
    email_candidat: String(extracted.email || ''),
    telephone: String(extracted.telephone || ''),
    nationalite: escapeSql(extracted.nationalite || ''),
    genre: genre,
    annees_experience: Number(extracted.annees_experience || 0),
    niveau_formation: escapeSql(extracted.niveau_formation || ''),
    domaine_formation: escapeSql(extracted.domaine_formation || ''),
    dernier_poste: escapeSql(extracted.dernier_poste || ''),
    secteurs_exp: escapeJson(extracted.secteurs_exp || []),
    certifications: escapeJson(extracted.certifications || []),
    langues: escapeJson(extracted.langues || []),
    competences_cles: escapeJson(extracted.competences_cles || []),
    points_forts: escapeJson(scoring.points_forts || []),
    points_faibles: escapeJson(scoring.points_faibles || []),
    score: score,
    score_justification: escapeSql(scoring.score_justification || ''),
    recommendation: String(scoring.recommendation || 'A_ETUDIER'),
    secteurs_exp_raw: extracted.secteurs_exp || [],
    competences_cles_raw: extracted.competences_cles || []
  }
}];

const formatterData = $node['Formatter candidature'].json;
const candidature_id = $node['Postgres — Enregistrer candidature'].json.id;

const secteurs = formatterData.secteurs_exp_raw || [];
const competences = formatterData.competences_cles_raw || [];

const text = [
  'Poste : ' + formatterData.poste,
  formatterData.annees_experience + ' ans d\'expérience',
  formatterData.dernier_poste ? 'Dernier poste : ' + formatterData.dernier_poste : '',
  formatterData.niveau_formation ? 'Formation : ' + formatterData.niveau_formation + ' ' + formatterData.domaine_formation : '',
  competences.length > 0 ? 'Compétences : ' + competences.join(', ') : '',
  secteurs.length > 0 ? 'Secteurs : ' + secteurs.join(', ') : '',
  formatterData.nationalite ? 'Nationalité : ' + formatterData.nationalite : ''
].filter(s => s && s.trim()).join('. ');

return [{
  json: {
    embedding_text: text,
    candidature_id: candidature_id
  }
}];

const embeddingResp = $input.all()[0].json;
const prepData = $node['Préparer texte embedding'].json;
const candidature_id = prepData.candidature_id;

const embedding = embeddingResp.data?.[0]?.embedding;
if (!embedding || !Array.isArray(embedding)) {
  throw new Error('Embedding invalide reçu de OpenAI pour candidature ' + candidature_id);
}

const vectorStr = '[' + embedding.join(',') + ']';

const q = "INSERT INTO candidature_embeddings (candidature_id, embedding, model, created_at, updated_at) VALUES (" +
  candidature_id + ", '" + vectorStr + "'::vector, 'text-embedding-3-small', NOW(), NOW()) " +
  "ON CONFLICT (candidature_id) DO UPDATE SET embedding = EXCLUDED.embedding, updated_at = NOW()";

return [{ json: { insert_query: q, candidature_id: candidature_id } }];
